//! mod_f64_floored ground-truth pin (issue #131, Z-131-FLOORMOD).
//!
//! GENERATED from CPython (the oracle IS Python; the SPEC floored law
//! "sign follows divisor" is what Python implements). Rows are f64
//! bit-patterns as hex strings:
//! * `mod` — 3028 (a, b) -> remainder rows: the full edge-value
//!   cross product (0.0/-0.0/integers/halves/1e10/1e300/1e-10/±inf/NaN)
//!   plus 2500 seeded random pairs (seed 20261009). Zero divisors are
//!   excluded (the caller's stress contract).
//! * `dm` — 1905 divmod rows: q = (a/b).floor() (the engine's
//!   FloorDiv float arm) and r = the same mod law, pinned TOGETHER —
//!   divmod's "parity by construction" contract is only honest if both
//!   halves match Python's pair.
//!
//! The issue's four filing rows are in-table via the edge cross product.
//! Never hand-edit a row — regenerate from Python.

use operon::num_exact::{divmod_f64, mod_f64_floored};

fn bits(h: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(h, 16).unwrap())
}

